57	        FormaPagamento formaPagamento = FormaPagamentoFactory.criar(pedido.formaPagamento());
58	        if (formaPagamento == null) {
59	            throw new ValidationException("FORMA_PAGAMENTO_INVALIDA");
60	        }
61	
62	        int numeroParcelas = pedido.parcelas() != null ? pedido.parcelas() : 1;
63	        if (!formaPagamento.estaDisponivel(BigDecimal.ZERO, numeroParcelas)) {
64	            throw new ValidationException("PARCELAMENTO_INVALIDO");
65	        }
66	
67	        BigDecimal subtotalProdutos = calcularSubtotalProdutos(pedido.itens());
68	
69	        BigDecimal frete = nivelClube.temFreteGratis()
70	            ? BigDecimal.ZERO.setScale(2)
71	            : modalidade.calcularFrete(pedido.itens());
72	
73	        BigDecimal descontoCupom = BigDecimal.ZERO.setScale(2);
74	        if (pedido.cupom() != null && !pedido.cupom().isEmpty()) {
75	            Cupom cupom = CupomFactory.criar(pedido.cupom());
76	            descontoCupom = cupom.calcularDesconto(subtotalProdutos, frete, pedido.itens());
77	        }
78	
79	        BigDecimal totalPedido = subtotalProdutos
80	            .subtract(descontoCupom)
81	            .add(frete)
82	            .add(seguro);
83	
84	        if (!formaPagamento.estaDisponivel(totalPedido, numeroParcelas)) {
85	            throw new ValidationException("FORMA_PAGAMENTO_INDISPONIVEL");
86	        }
87	
88	        BigDecimal ajustePagamento = formaPagamento.calcularAjuste(totalPedido, numeroParcelas);
89	        BigDecimal totalFinal = totalPedido.add(ajustePagamento);
90	
91	        BigDecimal valorParcela = totalFinal
92	            .divide(BigDecimal.valueOf(numeroParcelas), 2, RoundingMode.HALF_EVEN);
93	
94	        BigDecimal creditoProximaCompra = nivelClube.calcularCredito(subtotalProdutos);
95	        boolean brinde = nivelClube.ganhouBrinde(subtotalProdutos);
96	
97	        return new ResumoPedido(
98	            subtotalProdutos,
99	            descontoCupom,
100	            frete,
101	            modalidade.obterPrazo(),
102	            seguro,
103	            ajustePagamento,
104	            totalFinal,
105	            numeroParcelas,
106	            valorParcela,
107	            creditoProximaCompra,
108	            brinde
109	        );
110	    }
111	
112	    private BigDecimal calcularSubtotalProdutos(java.util.List<ItemCarrinho> itens) {
113	        return itens.stream()
114	            .map(item -> item.precoUnitario().multiply(BigDecimal.valueOf(item.quantidade())))
115	            .reduce(BigDecimal.ZERO, BigDecimal::add)
116	            .setScale(2, RoundingMode.HALF_EVEN);
117	    }
118	
119	    private void validarPedido(Pedido pedido) {
120	        if (pedido.itens() == null || pedido.itens().isEmpty()) {
121	            throw new ValidationException("PEDIDO_INVALIDO");
122	        }
123	
124	        for (ItemCarrinho item : pedido.itens()) {
125	            if (item.precoUnitario() == null || item.precoUnitario().compareTo(BigDecimal.ZERO) <= 0 ||
126	                item.quantidade() <= 0 ||
127	                item.pesoKg() == null || item.pesoKg().compareTo(BigDecimal.ZERO) <= 0) {
128	                throw new ValidationException("PEDIDO_INVALIDO");
129	            }
130	        }
131	    }
132	
133	    public static class ValidationException extends RuntimeException {
134	        public ValidationException(String message) {
135	            super(message);
136	        }
137	    }
138	}
