3	import java.math.BigDecimal;
4	import java.math.RoundingMode;
5	
6	public class Cartao implements FormaPagamento {
7	
8	    @Override
9	    public BigDecimal calcularAjuste(BigDecimal totalPedido, int parcelas) {
10	        if (parcelas <= 3) {
11	            return BigDecimal.ZERO.setScale(2);
12	        }
13	
14	        BigDecimal taxa = new BigDecimal("0.0199");
15	        BigDecimal fator = BigDecimal.ONE.add(taxa).pow(parcelas);
16	        BigDecimal denominador = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(fator, 10, RoundingMode.HALF_EVEN));
17	
18	        BigDecimal valorParcela = totalPedido
19	            .multiply(taxa)
20	            .divide(denominador, 2, RoundingMode.HALF_EVEN);
21	
22	        BigDecimal totalComJuros = valorParcela.multiply(BigDecimal.valueOf(parcelas));
23	
24	        return totalComJuros.subtract(totalPedido);
25	    }
26	
27	    @Override
28	    public boolean estaDisponivel(BigDecimal totalPedido, int parcelas) {
29	        return parcelas >= 1 && parcelas <= 12;
30	    }
31	}
